  traffic.manualClock=true;traffic.manualTime=18;m.BeginRide();var j=traffic.junctions[0];var u=traffic.mainDirection;var line=j.center-u*14+TrafficSystem.Right(u)*2.5f;m.CheckSignal(line-u,line+u);bool red=m.ledger.Score==88;m.CheckSignal(line-u,line+u);bool duplicate=m.ledger.Score==88;traffic.manualTime=1;m.CheckSignal(line-u,line+u);bool green=m.ledger.Score==88;
