  Move(new Vector3(-500,0,-500),Vector3.forward);yield return new WaitForSeconds(1);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=new Vector3(-500,1,-491);wall.transform.localScale=new Vector3(8,2,1);t.body.velocity=Vector3.forward*10;yield return new WaitForSeconds(2);bool collision=m.collisionEvents>0;Debug.Log("STABILITY collision "+m.collisionDiagnostic+" taxi="+t.transform.position);Destroy(wall);
