  for(int i=0;i<travel.Length;i++){float moved=traffic.cars[i].totalTravel-travel[i];Debug.Log("STABILITY mixed "+i+" moved="+moved+" secondWindow="+(traffic.cars[i].totalTravel-halfway[i])+" blocked="+traffic.cars[i].blockedName);mixed&=halfway[i]-travel[i]>5&&traffic.cars[i].totalTravel-halfway[i]>5;traffic.cars[i].Recycle();traffic.cars[i].enabled=false;}traffic.manualClock=true;
  bool turns=true;int turned=0;
