  var lead=traffic.cars[0];var follow=traffic.cars[1];traffic.manualTime=11.9f;lead.Place(lead.route.stops[0].distance-1);lead.enabled=true;yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();bool reserved=traffic.junctions[0].owner==lead;traffic.manualTime=12.1f;yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();bool released=traffic.junctions[0].owner==null;lead.Recycle();lead.enabled=false;
